insert into chart_templates
  (country, code, name, name_i18n, is_default, audience, statements,
   certification_status, legal_reference, source_key)
values
  ('ES', 'default', 'PGC — Plan General de Contabilidad (selección para pymes)', '{"en":"PGC — Spanish General Accounting Plan (selection for SMEs)"}'::jsonb, true, 'companies', array['ES-PGC-BA', 'ES-PGC-PGA']::text[], null, 'Real Decreto 1514/2007, Plan General de Contabilidad, cuarta parte — cuadro de cuentas. Selección de 220 cuentas de los grupos 1 a 7, con los códigos y las denominaciones oficiales; los grupos 8 y 9 (gastos e ingresos imputados al patrimonio neto) quedan fuera. La introducción del Real Decreto 1514/2007 dice que el cuadro de cuentas «seguirá sin ser obligatorio en cuanto a la numeración de las cuentas y denominación de las mismas», pero los códigos son los que usa toda la práctica española y los que el PGC de PYMES (Real Decreto 1515/2007) repite', 'pgc')
on conflict (country, code) do update set
