  ('ES', 'ES-S-EXE', 'Operación interior exenta', '{"en":"Domestic exempt supply"}'::jsonb, null, 'percent', 0, 'sale', 'exempt', date '1993-01-01', null, 'Ley 37/1992, art. 20 — exenciones en operaciones interiores. El modelo 303 no declara estas operaciones en el periodo; figuran en el modelo 390 o, para quien está exonerado de él, en la casilla 83 del último periodo del año, que este paquete no transcribe', 'E', 'VATEX-EU-132', 140, 'vat', true, array['supply_nature']::tax_condition[], null, false, false, null, 'liva', null, null, null),
  ('ES', 'ES-S-EXP', 'Exportación exenta', '{"en":"Exempt export"}'::jsonb, null, 'percent', 0, 'sale', 'export', date '1993-01-01', null, 'Ley 37/1992, art. 21 — exención de las exportaciones, incluidos los envíos definitivos a Canarias, Ceuta y Melilla. Modelo 303, casilla 60', 'G', 'VATEX-EU-G', 120, 'vat', true, array['transport_evidence']::tax_condition[], null, false, false, null, 'liva', null, null, null),
  ('ES', 'ES-S-ICG', 'Entrega intracomunitaria de bienes exenta', '{"en":"Exempt intra-Community supply of goods"}'::jsonb, null, 'percent', 0, 'sale', 'intracom_goods', date '1993-01-01', null, 'Ley 37/1992, art. 25 — exención de las entregas de bienes destinados a otro Estado miembro. Modelo 303, casilla 59; se detalla en el modelo 349 con la clave E', 'K', 'VATEX-EU-IC', 100, 'vat', true, array['transport_evidence', 'buyer_status']::tax_condition[], null, false, false, null, 'liva', null, null, null),
  ('ES', 'ES-S-ICS', 'Prestación intracomunitaria de servicios (inversión del sujeto pasivo)', '{"en":"Intra-Community supply of services (reverse charge)"}'::jsonb, null, 'percent', 0, 'sale', 'intracom_services', date '2010-01-01', null, 'Ley 37/1992, art. 69.Uno.1.º — lugar de realización en la sede del destinatario empresario, y art. 84.Uno.2.º — sujeto pasivo el destinatario. Modelo 303, casilla 59; se detalla en el modelo 349 con la clave S', 'K', 'VATEX-EU-IC', 110, 'vat', true, array['buyer_status']::tax_condition[], null, false, false, null, 'liva', null, null, null),
  ('ES', 'ES-S-ISP', 'Operación interior con inversión del sujeto pasivo', '{"en":"Domestic supply, reverse charge"}'::jsonb, null, 'percent', 0, 'sale', 'domestic_reverse_charge', date '2012-10-31', null, 'Ley 37/1992, art. 84.Uno.2.º, letras b), c), e), f) y g) — el destinatario empresario es el sujeto pasivo: oro, desechos, inmuebles en ejecución de garantía o con renuncia a la exención, ejecuciones de obra de urbanización, construcción o rehabilitación y determinados productos electrónicos. Modelo 303, casilla 122. Validez desde el 31 de octubre de 2012, entrada en vigor de la letra f), añadida por la Ley 7/2012, de 29 de octubre, art. 5.4', 'AE', 'VATEX-EU-AE', 130, 'vat', true, array['supply_nature', 'buyer_status']::tax_condition[], null, false, false, null, 'liva', null, null, null),
  ('ES', 'ES-S-NS', 'Operación no sujeta por reglas de localización', '{"en":"Supply not subject to Spanish VAT under the place-of-supply rules"}'::jsonb, null, 'percent', 0, 'sale', 'not_subject', date '1993-01-01', null, 'Ley 37/1992, arts. 68 a 70 — lugar de realización; la operación se localiza fuera del territorio de aplicación del impuesto. Modelo 303, casilla 120 (excepto las prestaciones intracomunitarias de la casilla 59 y las acogidas a la ventanilla única de la casilla 123)', 'O', 'VATEX-EU-O', 150, 'vat', true, array['supply_nature']::tax_condition[], null, false, false, null, 'liva', null, null, null)
