insert into tax_report_templates
  (country, code, name, periods, period_default, valid_from, valid_to, legal_reference,
   is_periodic_return, deadline_rule, deadline_day, deadline_plus_days,
   deadline_reference, deadline_source_key, file_format)
values
  ('ES', 'ES-303', 'Modelo 303 — IVA. Autoliquidación', array['month', 'quarter']::declaration_period[], 'quarter'::declaration_period, date '2024-07-01', null, 'Orden EHA/3786/2008 — modelo 303; anexo I en la redacción de la Orden HAC/819/2024 (casillas 153 a 155 y 165 a 170, aplicable desde septiembre y el tercer trimestre de 2024, de ahí valid_from) y después de la Orden HAC/27/2026, anexo III, aplicable desde febrero y el segundo trimestre de 2026, que no cambia ninguna casilla transcrita aquí. Cadencia: Reglamento del IVA, art. 71.3 — el periodo de liquidación coincide con el trimestre natural, y con el mes natural para quien superó 6.010.121,04 € de volumen de operaciones el año anterior, está inscrito en el registro de devolución mensual (art. 30), aplica el régimen del grupo de entidades o es titular de un depósito fiscal de carburantes. El trimestre es la regla que la ley da a todos, y la que se propone', true,'day_of_month_after_period'::filing_deadline_rule, 20, null, 'Reglamento del IVA, art. 71.4 — durante los veinte primeros días naturales del mes siguiente al periodo. Dos excepciones que la regla no puede decir y que el declarante debe aplicar: la autoliquidación del último periodo del año se presenta durante los treinta primeros días naturales de enero, y quien lleva los libros registro por el SII (art. 62.6, primer párrafo) presenta en los treinta primeros días naturales del mes siguiente, o hasta el último día de febrero para enero', 'riva', null)
on conflict (country, code) do update set
  name                = excluded.name,
  periods             = excluded.periods,
  period_default      = excluded.period_default,
  valid_from          = excluded.valid_from,
  valid_to            = excluded.valid_to,
  legal_reference     = excluded.legal_reference,
  is_periodic_return  = excluded.is_periodic_return,
  deadline_rule       = excluded.deadline_rule,
  deadline_day        = excluded.deadline_day,
  deadline_plus_days  = excluded.deadline_plus_days,
  deadline_reference  = excluded.deadline_reference,
  deadline_source_key = excluded.deadline_source_key,
  file_format         = excluded.file_format;

