update country_defaults set
  numbering_gapless             = true,
  number_format                 = '{CODE}/{YYYY}/{NNNN}',
  legal_payment_days            = 30,
  late_payment_reference        = 'Ley 3/2004, art. 7.2 — interés de demora: el tipo de la operación principal de financiación más reciente del Banco Central Europeo anterior al semestre, más ocho puntos porcentuales; art. 8.1 — indemnización fija de 40 euros por costes de cobro',
  numbering_legal_reference     = 'Real Decreto 1619/2012, art. 6.1.a) — número y, en su caso, serie; «la numeración de las facturas dentro de cada serie será correlativa». Las facturas rectificativas van en una serie específica. El reglamento no obliga a reiniciar la numeración cada año; una serie por año es una de las series separadas que el mismo artículo admite, y es la que este paquete propone',
  numbering_source_key          = 'rf',
  payment_terms_legal_reference = 'Ley 3/2004, art. 4.1 — a falta de pacto, treinta días naturales desde la recepción de las mercancías o la prestación de los servicios; art. 4.3 — el plazo pactado no puede superar sesenta días naturales',
  payment_terms_source_key      = 'morosidad',
  tax_point_rule                = 'earliest_of_delivery_or_payment',
  tax_point_legal_reference     = 'Ley 37/1992, art. 75.Uno — el impuesto se devenga en las entregas de bienes cuando tiene lugar su puesta a disposición del adquirente, y en las prestaciones de servicios cuando se prestan; art. 75.Dos — en las operaciones con pagos anticipados, en el momento del cobro total o parcial del precio por los importes efectivamente percibidos. El devengo es, pues, el primero de los dos hechos; la fecha de la factura no lo fija',
  tax_point_source_key          = 'liva',
  posted_edit_policy            = 'reversal_only',
  posted_edit_policy_legal_reference = 'Código de Comercio, art. 29.1 — los libros se llevan sin espacios en blanco, interpolaciones, tachaduras ni raspaduras, y los errores se salvan a continuación; Real Decreto 1619/2012, art. 15 — una factura se corrige con una factura rectificativa, en serie específica (art. 6.1.a). Una factura contabilizada se anula por rectificativa, nunca se devuelve a borrador',
  posted_edit_policy_source_key = 'codigo-comercio',
  einvoice_profile              = null,
  einvoice_mandatory_from       = null,
  einvoice_legal_reference      = 'Ley 18/2022, art. 12, que modifica el art. 2 bis de la Ley 56/2007, y Real Decreto 238/2026, en vigor desde el 20 de abril de 2026 — factura electrónica obligatoria entre empresarios y profesionales, ajustada al modelo semántico EN 16931 en sintaxis UBL (la de referencia de la solución pública), CII, EDIFACT o Facturae (art. 12 del real decreto). La obligación empieza doce meses después de la entrada en vigor de la orden ministerial que desarrolla la solución pública de facturación electrónica para quien superó 8 millones de euros de volumen de operaciones el año anterior, y veinticuatro meses después para los demás (disposición final cuarta). A 21 de septiembre de 2026 esta orden no se ha encontrado publicada en el BOE, así que no hay fecha que escribir: mandatory_from queda vacío y profile también, porque ninguna pieza de packages/formats escribe todavía una factura española y declarar un perfil sería afirmar lo contrario. El esquema 9920 (Agencia Española de Administración Tributaria) identifica el NIF, que en España es a la vez el identificador de la empresa y el de IVA. SII (Real Decreto 596/2016) y VERI*FACTU (Real Decreto 1007/2023) son obligaciones de registro y remisión de facturas, no un formato de factura: véase el README',
  einvoice_source_key           = 'rd-238-2026',
  party_scheme                  = '9920',
  vat_scheme                    = '9920',
  bank_statement_formats        = array['camt.053', 'mt940']::text[],
  payment_formats               = array['pain.001', 'pain.008']::text[],
  fiscal_year_default           = 'calendar'
 where country = 'ES';

insert into legal_mention_templates
  (country, code, applies_when, text, text_i18n, sequence, valid_from, valid_to, legal_reference)
values
  ('ES', 'reverse_charge', 'reverse_charge', 'Inversión del sujeto pasivo', '{"en":"Reverse charge"}'::jsonb, 10, date '1970-01-01', null, 'Real Decreto 1619/2012, Reglamento de facturación, art. 6.1.m) — «en el caso de que el sujeto pasivo del Impuesto sea el adquirente o el destinatario de la operación, la mención “inversión del sujeto pasivo”»'),
  ('ES', 'intracom_goods', 'intra_eu_goods', 'Entrega intracomunitaria exenta — artículo 25 de la Ley 37/1992 del IVA; artículo 138 de la Directiva 2006/112/CE.', '{"en":"Exempt intra-Community supply — article 25 of the Spanish VAT Act (Ley 37/1992); article 138 of Directive 2006/112/EC."}'::jsonb, 20, date '1970-01-01', null, 'Real Decreto 1619/2012, art. 6.1.j) — referencia a las disposiciones de la Directiva 2006/112/CE o de la Ley del Impuesto que declaran exenta la operación; art. 6.1.d).1.º — la factura consigna el NIF del destinatario'),
  ('ES', 'intracom_services', 'intra_eu_services', 'Inversión del sujeto pasivo — artículos 44 y 196 de la Directiva 2006/112/CE.', '{"en":"Reverse charge — articles 44 and 196 of Directive 2006/112/EC."}'::jsonb, 30, date '1970-01-01', null, 'Real Decreto 1619/2012, art. 6.1.m) — mención «inversión del sujeto pasivo» cuando el destinatario es el sujeto pasivo'),
  ('ES', 'export', 'export', 'Exportación exenta — artículo 21 de la Ley 37/1992 del IVA.', '{"en":"Exempt export — article 21 of the Spanish VAT Act (Ley 37/1992)."}'::jsonb, 40, date '1970-01-01', null, 'Real Decreto 1619/2012, art. 6.1.j)'),
  ('ES', 'exempt', 'exempt', 'Operación exenta — artículo 20 de la Ley 37/1992 del IVA.', '{"en":"Exempt supply — article 20 of the Spanish VAT Act (Ley 37/1992)."}'::jsonb, 50, date '1970-01-01', null, 'Real Decreto 1619/2012, art. 6.1.j) — basta la referencia al precepto o la indicación de que la operación está exenta'),
  ('ES', 'cash_basis', 'cash_basis', 'Régimen especial del criterio de caja', '{"en":"Special cash accounting scheme"}'::jsonb, 60, date '1970-01-01', null, 'Real Decreto 1619/2012, art. 6.1.p) — mención «régimen especial del criterio de caja»; Ley 37/1992, arts. 163 decies a 163 sexiesdecies. Ningún impuesto de este paquete aplica el régimen, así que la mención no sale en ninguna factura hasta que uno lo haga')
on conflict (country, code) do update set
  applies_when    = excluded.applies_when,
  text            = excluded.text,
  text_i18n       = excluded.text_i18n,
  sequence        = excluded.sequence,
  valid_from      = excluded.valid_from,
  valid_to        = excluded.valid_to,
  legal_reference = excluded.legal_reference;
